START = datetime.date(2026, 9, 29)   # вторник
DAYS = (1, 3, 5)                      # вторник, четверг, суббота


def dates(n, start=START):
    out, d = [], start
    while len(out) < n:
        if d.weekday() in DAYS and d >= start:
            out.append(d)
        d += datetime.timedelta(days=1)
    return out


def main():
    path = 'content/schedule.json'
    if os.path.exists(path) and '--force' not in sys.argv:
        print('%s уже есть — статусы публикаций затирать нельзя. Нужен --force.' % path)
        return 1

    items = []
    for cluster, ckey, topics in CLUSTERS:
        for slug, title, query, freq, who, data in topics:
            items.append({
                'slug': slug, 'title': title, 'cluster': cluster, 'cluster_key': ckey,
                'query': query, 'freq': freq, 'audience': who, 'data_block': data,
                'status': 'planned', 'date': None, 'published_at': None, 'words': 0,
            })

    # Порядок публикаций: кластеры чередуются, чтобы сайт не рос одной темой,
    # а внутри кластера — сначала самые частотные.
    by_cluster = {}
    for it in items:
        by_cluster.setdefault(it['cluster_key'], []).append(it)
    for lst in by_cluster.values():
        lst.sort(key=lambda x: -x['freq'])
    # Питерские идут чаще в начале: заявки нужны сейчас, а не через год.
    order, keys = [], list(by_cluster)
    keys.sort(key=lambda k: 0 if k == 'spb' else 1)
    while any(by_cluster.values()):
        for k in keys:
            if by_cluster[k]:
                order.append(by_cluster[k].pop(0))

    for it, d in zip(order, dates(len(order))):
        it['date'] = d.isoformat()

    os.makedirs('content', exist_ok=True)
    io.open(path, 'w', encoding='utf-8').write(json.dumps({
        'generated': datetime.date.today().isoformat(),
        'cadence': 'вторник, четверг, суббота',
        'items': order,
    }, ensure_ascii=False, indent=1))

    print('статей: %d' % len(order))
    print('с %s по %s' % (order[0]['date'], order[-1]['date']))
    for cluster, ckey, topics in CLUSTERS:
        print('  %-42s %3d' % (cluster, len(topics)))
    return 0


if __name__ == '__main__':
    sys.exit(main())
